import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"蹇","description":"周易集解 - 蹇","frontmatter":{"title":"蹇","description":"周易集解 - 蹇"},"headers":[],"relativePath":"zh/classics/jijie/039.md","filePath":"zh/classics/jijie/039.md"}'),l={name:"zh/classics/jijie/039.md"};function n(d,a,p,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="蹇" tabindex="-1">蹇 <a class="header-anchor" href="#蹇" aria-label="Permalink to “蹇”">​</a></h1><h2 id="蹇-1" tabindex="-1">蹇 <a class="header-anchor" href="#蹇-1" aria-label="Permalink to “蹇”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>蹇，利西南，不利東北。利見大人。貞吉。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《序卦》曰：乖必有難，故受之以蹇。蹇者，難也。</p><p>崔憬曰：二女同居，其志乖而難生，故曰｢乖必有難｣也。</p><p>虞翻曰：觀上反三也。坤，西南卦。五在坤中，坎為月，月生西南，故利西南。往得中，謂西南得朋也。</p><p>虞翻曰：謂三也。艮東北之卦。月消於艮，喪乙滅癸。故｢不利東北，其道窮也｣。則東北喪朋矣。</p><p>虞翻曰：離為見，大人謂五。二得位應五。故｢利見大人，往有功也｣。</p><p>虞翻曰：謂五當位正邦，故貞吉也。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：蹇，難也，險在前也。見險而能止，知矣哉。蹇，利西南，往得中也。不利東北，其道窮也。利見大人，往有功也。當位貞吉，以正邦也。蹇之時用大矣哉。</p><h2 id="彖传注" tabindex="-1">彖传注 <a class="header-anchor" href="#彖传注" aria-label="Permalink to “彖传注”">​</a></h2><p>虞翻曰：離見坎險。艮為止，觀乾為智，故知矣哉。</p><p>荀爽曰：西南謂坤。升二往居坤五，故得中也。</p><p>荀爽曰：東北，艮也。艮在坎下。見險而止，故其道窮也。</p><p>虞翻曰：大人謂五。二往應五，五多功，故往有功也。</p><p>荀爽曰：謂五當尊位。正居是，群陰順從，故能正邦國。</p><p>虞翻曰：謂坎月生西南而終東北。震象出庚，兌象見丁，乾象盈甲，巽象退辛，艮象消丙，坤象窮乙，喪滅於癸，終則復始，以生萬物，故用大矣。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：山上有水，蹇。君子以反身脩德。</p><h2 id="象传注" tabindex="-1">象传注 <a class="header-anchor" href="#象传注" aria-label="Permalink to “象传注”">​</a></h2><p>崔憬曰：山上至險，加之以水，蹇之象也。</p><p>虞翻曰：君子謂觀。乾坤為身，觀上反三，故反身。陽在三，進德脩業，故以反身脩德。孔子曰：德之不脩，是吾憂也。</p><h2 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h2><p>初六，往蹇，來譽。</p><h2 id="初六注" tabindex="-1">初六注 <a class="header-anchor" href="#初六注" aria-label="Permalink to “初六注”">​</a></h2><p>虞翻曰：譽謂二，二多譽也。失位應陰，往歷坎險，故往蹇。變而得位，以陽承二，故來而譽矣。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：往蹇來譽，宜待也。</p><h2 id="象传注-1" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-1" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：艮為時，謂變之正以待四也。</p><h2 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h2><p>六二，王臣蹇蹇，匪躬之故。</p><h2 id="六二注" tabindex="-1">六二注 <a class="header-anchor" href="#六二注" aria-label="Permalink to “六二注”">​</a></h2><p>虞翻曰：觀乾為王；坤為臣，為躬；坎為蹇也。之應涉坤，二五俱坎，故王臣蹇蹇。觀上之三，折坤之體，臣道得正，故匪躬之故。《象》曰｢終無尤也｣。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：王臣蹇蹇，終無尤也。</p><h2 id="象传注-2" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-2" aria-label="Permalink to “象传注”">​</a></h2><p>侯果曰：處艮之二，上應於五。五在坎中，險而又險。志在匡弼，匪惜其躬。故曰｢王臣蹇蹇，匪躬之故｣。輔君以此，終無尤也。</p><h2 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h2><p>九三，往蹇，來反。</p><h2 id="九三注" tabindex="-1">九三注 <a class="header-anchor" href="#九三注" aria-label="Permalink to “九三注”">​</a></h2><p>虞翻曰：應正歷險，故往蹇。反身據二，故來反也。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：往蹇來反，內喜之也。</p><h2 id="象传注-3" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-3" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：內喜，謂二陰也。</p><h2 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h2><p>六四，往蹇，來連。</p><h2 id="六四注" tabindex="-1">六四注 <a class="header-anchor" href="#六四注" aria-label="Permalink to “六四注”">​</a></h2><p>虞翻曰：連，輦。蹇，難也。在兩坎間，進則無應，故往蹇。退初介三，故來連也。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：往蹇來連，當位實也。</p><h2 id="象传注-4" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-4" aria-label="Permalink to “象传注”">​</a></h2><p>荀爽曰：蹇難之世，不安其所。欲往之三，不得承陽。故曰往蹇也。來還承五，則與至尊相連，故曰來連也。處正承陽，故曰當位實也。</p><h2 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h2><p>九五，大蹇，朋來。</p><h2 id="九五注" tabindex="-1">九五注 <a class="header-anchor" href="#九五注" aria-label="Permalink to “九五注”">​</a></h2><p>虞翻曰：當位正邦，故大蹇。睽兌為朋，故朋來也。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：大蹇朋來，以中節也。</p><h2 id="象传注-5" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-5" aria-label="Permalink to “象传注”">​</a></h2><p>乾寶曰：在險之中，而當王位，故曰｢大蹇｣。此蓋以託文王為紂所囚也。承上據四應二，眾陰並至。此蓋以託四臣能以權智相救也。故曰以中節也。</p><h2 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h2><p>上六，往蹇，來碩吉，利見大人。</p><h2 id="上六注" tabindex="-1">上六注 <a class="header-anchor" href="#上六注" aria-label="Permalink to “上六注”">​</a></h2><p>虞翻曰：陰在險上，變失位，故往蹇。碩謂三，艮為碩，退來之三，故來碩。得位有應，故吉也。離為見，大人謂五，故利見大人矣。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：往蹇來碩，志在內也。利見大人，以從貴也。</p><h2 id="象传注-6" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-6" aria-label="Permalink to “象传注”">​</a></h2><p>侯果曰：處蹇之極，體猶在坎，水無所之，故曰往蹇。來而複位，下應於三，三德碩大，故曰來碩。三為內主，五為大人。若志在內，心附於五。則利見大人也。</p><p>案：三互體離，離為明目，五為大人，利見大人之象也。</p>',74)])])}const f=e(l,[["render",n]]);export{b as __pageData,f as default};
